import os
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Tuple

import boto3


@dataclass
class ExtractedField:
    value: Any
    confidence: float


@dataclass
class ExtractionResult:
    fields: Dict[str, ExtractedField]
    missing_required_fields: List[str]
    low_confidence_fields: List[str]
    all_required_valid: bool


class StructuredDocumentExtractionError(ValueError):
    pass


def _normalize_confidence(confidence: Any) -> float:
    if confidence is None:
        return 0.0
    try:
        c = float(confidence)
    except (TypeError, ValueError):
        return 0.0
    if c > 1.0:
        c = c / 100.0
    return max(0.0, min(1.0, c))


def _extract_expense_fields(textract_response: Dict[str, Any]) -> Dict[str, ExtractedField]:
    result: Dict[str, ExtractedField] = {}

    documents = textract_response.get("ExpenseDocuments", []) or []
    for doc in documents:
        summary_fields = doc.get("SummaryFields", []) or []
        for item in summary_fields:
            field_type = (item.get("Type") or {}).get("Text")
            value = (item.get("ValueDetection") or {}).get("Text")
            confidence = _normalize_confidence((item.get("ValueDetection") or {}).get("Confidence"))

            if field_type and field_type not in result:
                result[field_type] = ExtractedField(value=value, confidence=confidence)

    return result


def validate_structured_document(
    document_bytes: bytes,
    required_fields: List[str],
    min_confidence: float = 0.8,
    region_name: Optional[str] = None,
) -> ExtractionResult:
    """
    Validate required structured fields and confidence scores using Amazon Textract AnalyzeExpense.

    Args:
        document_bytes: Raw bytes for an image or PDF document.
        required_fields: List of required Textract summary field names, e.g. ["INVOICE_RECEIPT_ID", "VENDOR_NAME"].
        min_confidence: Minimum normalized confidence (0-1) required for each required field.
        region_name: Optional AWS region override.

    Returns:
        ExtractionResult with extracted fields and validation status.

    Raises:
        StructuredDocumentExtractionError: For AWS/API or validation input issues.
    """
    if not document_bytes:
        raise StructuredDocumentExtractionError("document_bytes must not be empty.")
    if not required_fields:
        raise StructuredDocumentExtractionError("required_fields must not be empty.")
    if not (0.0 <= min_confidence <= 1.0):
        raise StructuredDocumentExtractionError("min_confidence must be between 0.0 and 1.0.")

    textract_kwargs: Dict[str, Any] = {}
    if region_name:
        textract_kwargs["region_name"] = region_name

    client = boto3.client("textract", **textract_kwargs)

    try:
        response = client.analyze_expense(Document={"Bytes": document_bytes})
    except Exception as exc:
        raise StructuredDocumentExtractionError(f"Textract AnalyzeExpense failed: {exc}") from exc

    extracted = _extract_expense_fields(response)

    missing_required_fields: List[str] = []
    low_confidence_fields: List[str] = []

    for field_name in required_fields:
        field = extracted.get(field_name)
        if field is None or field.value in (None, ""):
            missing_required_fields.append(field_name)
            continue
        if field.confidence < min_confidence:
            low_confidence_fields.append(field_name)

    all_required_valid = not missing_required_fields and not low_confidence_fields

    return ExtractionResult(
        fields=extracted,
        missing_required_fields=missing_required_fields,
        low_confidence_fields=low_confidence_fields,
        all_required_valid=all_required_valid,
    )
